INSERT INTO public.blog_seo (slug, title, description, image_url, page_type) VALUES ('in-car-ev-charging', 'In-Car EV Charging: Why OEMs Should Run Demand, Not Networks | NetworkCore', 'In-car EV charging needs a new architecture. Learn why OEMs should be demand partners — not network operators — and how NetworkCore''s clearing and settlement layer makes it work.', '/images/blog/in-car-ev-charging.jpg', 'blog');